// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address who) internal {
        uint256 before;
        try c.getBalance(who) returns (uint256 __r) { before = __r; } catch { return; }
        uint256 afterCall;
        try c.getBalance(who) returns (uint256 __r) { afterCall = __r; } catch { return; }
        assertTrue(afterCall == before);
    }

    function testFuzz_run(address who) public {
        vm.assume(who.code.length == 0 && uint160(who) > 0xffff && who != address(this) && who != address(c) && who != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && who != 0x000000000000000000636F6e736F6c652e6c6f67 && who != 0x4e59b44847b379578588920cA78FbF26c0B4956C && who != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(who);
    }

    receive() external payable {}
}
